import {
  pgTable,
  serial,
  varchar,
  text,
  timestamp,
  integer,
} from 'drizzle-orm/pg-core';
import { relations } from 'drizzle-orm';

export const users = pgTable('users', {
  id: serial('id').primaryKey(),
  name: varchar('name', { length: 100 }),
  email: varchar('email', { length: 255 }).notNull().unique(),
  passwordHash: text('password_hash').notNull(),
  role: varchar('role', { length: 20 }).notNull().default('member'),
  createdAt: timestamp('created_at').notNull().defaultNow(),
  updatedAt: timestamp('updated_at').notNull().defaultNow(),
  deletedAt: timestamp('deleted_at'),
});

export const teams = pgTable('teams', {
  id: serial('id').primaryKey(),
  name: varchar('name', { length: 100 }).notNull(),
  createdAt: timestamp('created_at').notNull().defaultNow(),
  updatedAt: timestamp('updated_at').notNull().defaultNow(),
  stripeCustomerId: text('stripe_customer_id').unique(),
  stripeSubscriptionId: text('stripe_subscription_id').unique(),
  stripeProductId: text('stripe_product_id'),
  planName: varchar('plan_name', { length: 50 }),
  subscriptionStatus: varchar('subscription_status', { length: 20 }),
});

export const teamMembers = pgTable('team_members', {
  id: serial('id').primaryKey(),
  userId: integer('user_id')
    .notNull()
    .references(() => users.id),
  teamId: integer('team_id')
    .notNull()
    .references(() => teams.id),
  role: varchar('role', { length: 50 }).notNull(),
  joinedAt: timestamp('joined_at').notNull().defaultNow(),
});

export const activityLogs = pgTable('activity_logs', {
  id: serial('id').primaryKey(),
  teamId: integer('team_id')
    .notNull()
    .references(() => teams.id),
  userId: integer('user_id').references(() => users.id),
  action: text('action').notNull(),
  timestamp: timestamp('timestamp').notNull().defaultNow(),
  ipAddress: varchar('ip_address', { length: 45 }),
});

export const invitations = pgTable('invitations', {
  id: serial('id').primaryKey(),
  teamId: integer('team_id')
    .notNull()
    .references(() => teams.id),
  email: varchar('email', { length: 255 }).notNull(),
  role: varchar('role', { length: 50 }).notNull(),
  invitedBy: integer('invited_by')
    .notNull()
    .references(() => users.id),
  invitedAt: timestamp('invited_at').notNull().defaultNow(),
  status: varchar('status', { length: 20 }).notNull().default('pending'),
});

export const teamsRelations = relations(teams, ({ many }) => ({
  teamMembers: many(teamMembers),
  activityLogs: many(activityLogs),
  invitations: many(invitations),
}));

export const usersRelations = relations(users, ({ many }) => ({
  teamMembers: many(teamMembers),
  invitationsSent: many(invitations),
}));

export const invitationsRelations = relations(invitations, ({ one }) => ({
  team: one(teams, {
    fields: [invitations.teamId],
    references: [teams.id],
  }),
  invitedBy: one(users, {
    fields: [invitations.invitedBy],
    references: [users.id],
  }),
}));

export const teamMembersRelations = relations(teamMembers, ({ one }) => ({
  user: one(users, {
    fields: [teamMembers.userId],
    references: [users.id],
  }),
  team: one(teams, {
    fields: [teamMembers.teamId],
    references: [teams.id],
  }),
}));

export const activityLogsRelations = relations(activityLogs, ({ one }) => ({
  team: one(teams, {
    fields: [activityLogs.teamId],
    references: [teams.id],
  }),
  user: one(users, {
    fields: [activityLogs.userId],
    references: [users.id],
  }),
}));

export type User = typeof users.$inferSelect;
export type NewUser = typeof users.$inferInsert;
export type Team = typeof teams.$inferSelect;
export type NewTeam = typeof teams.$inferInsert;
export type TeamMember = typeof teamMembers.$inferSelect;
export type NewTeamMember = typeof teamMembers.$inferInsert;
export type ActivityLog = typeof activityLogs.$inferSelect;
export type NewActivityLog = typeof activityLogs.$inferInsert;
export type Invitation = typeof invitations.$inferSelect;
export type NewInvitation = typeof invitations.$inferInsert;
export type TeamDataWithMembers = Team & {
  currentUserRole: TeamMember['role'];
  teamMembers: (TeamMember & {
    user: Pick<User, 'id' | 'name' | 'email'>;
  })[];
};

export enum ActivityType {
  SIGN_UP = 'SIGN_UP',
  SIGN_IN = 'SIGN_IN',
  SIGN_OUT = 'SIGN_OUT',
  UPDATE_PASSWORD = 'UPDATE_PASSWORD',
  DELETE_ACCOUNT = 'DELETE_ACCOUNT',
  UPDATE_ACCOUNT = 'UPDATE_ACCOUNT',
  CREATE_TEAM = 'CREATE_TEAM',
  REMOVE_TEAM_MEMBER = 'REMOVE_TEAM_MEMBER',
  INVITE_TEAM_MEMBER = 'INVITE_TEAM_MEMBER',
  ACCEPT_INVITATION = 'ACCEPT_INVITATION',
}

import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import { readFile } from 'node:fs/promises';
import { PGlite } from '@electric-sql/pglite';
import { PGLiteSocketServer } from '@electric-sql/pglite-socket';
import { renderToStaticMarkup } from 'react-dom/server';
import { SWRConfig } from 'swr';

// Exercise the application queries, actions, session verification and UI with SQL.
const request = vi.hoisted(() => ({ token: '' }));
vi.mock('next/headers', () => ({
  cookies: async () => ({
    get: (name: string) => name === 'session' && request.token
      ? { value: request.token }
      : undefined,
  }),
}));

let sql: PGlite;
let socket: PGLiteSocketServer;
let actions: typeof import('@/app/(login)/actions');
let queries: typeof import('@/lib/db/queries');
let session: typeof import('@/lib/auth/session');
let client: typeof import('@/lib/db/drizzle')['client'];
let Page: typeof import('@/app/(dashboard)/dashboard/page')['default'];
let GET: typeof import('@/app/api/team/route')['GET'];

beforeAll(async () => {
  sql = await PGlite.create();
  await sql.exec(await readFile('lib/db/migrations/0000_soft_the_anarchist.sql', 'utf8'));
  socket = new PGLiteSocketServer({ db: sql, port: 0, host: '127.0.0.1', maxConnections: 10 });
  await socket.start();
  process.env.POSTGRES_URL = `postgresql://postgres:postgres@${socket.getServerConn()}/postgres`;
  process.env.AUTH_SECRET = 'team-permissions-local-test-secret';
  process.env.STRIPE_SECRET_KEY = 'sk_test_local_no_payment_requests';
  actions = await import('@/app/(login)/actions');
  queries = await import('@/lib/db/queries');
  session = await import('@/lib/auth/session');
  ({ client } = await import('@/lib/db/drizzle'));
  ({ default: Page } = await import('@/app/(dashboard)/dashboard/page'));
  ({ GET } = await import('@/app/api/team/route'));
});

afterAll(async () => {
  await client?.end({ timeout: 3 });
  await socket?.stop();
  await sql?.close();
});

async function login(id: number) {
  request.token = await session.signToken({
    user: { id },
    expires: new Date(Date.now() + 60000).toISOString(),
  });
}

beforeEach(async () => {
  await sql.exec(`
    TRUNCATE activity_logs, invitations, team_members, teams, users RESTART IDENTITY CASCADE;
    INSERT INTO users(id,name,email,password_hash,role) VALUES
      (1,'Team owner','owner@fixture.invalid','unused','member'),
      (2,'Team member','member@fixture.invalid','unused','owner'),
      (3,'Other owner','other@fixture.invalid','unused','owner');
    INSERT INTO teams(id,name) VALUES (1,'Current team'), (2,'Other team');
    INSERT INTO team_members(id,user_id,team_id,role) VALUES
      (1,1,1,'owner'), (2,2,1,'member'), (3,3,2,'owner'), (4,2,2,'owner');
  `);
  await login(1);
});

async function snapshot() {
  return {
    members: (await sql.query<{ id: number }>('SELECT * FROM team_members ORDER BY id')).rows,
    invitations: (await sql.query('SELECT * FROM invitations ORDER BY id')).rows,
    activity: (await sql.query('SELECT * FROM activity_logs ORDER BY id')).rows,
  };
}

function invitationForm() {
  const form = new FormData();
  form.set('email', 'new@fixture.invalid');
  form.set('role', 'member');
  return form;
}

function removalForm(memberId: string | null) {
  const form = new FormData();
  if (memberId !== null) form.set('memberId', memberId);
  return form;
}

async function markup() {
  return renderToStaticMarkup(
    <SWRConfig value={{
      provider: () => new Map(),
      fallback: { '/api/user': await queries.getUser(), '/api/team': await queries.getTeamForUser() },
      revalidateOnMount: false,
    }}>
      <Page />
    </SWRConfig>,
  );
}

describe('team membership boundary regressions', () => {
  it.each([null, '', ' ', '0', '-2', '2.5', '2abc', '2e0', '0x2', 'Infinity', '2147483648', '9007199254740993'])(
    'rejects invalid FormData memberId %j without SQL or audit changes',
    async (memberId) => {
      const before = await snapshot();
      expect(await actions.removeTeamMember({}, removalForm(memberId))).toHaveProperty('error');
      expect(await snapshot()).toEqual(before);
    },
  );

  it('rejects a file submitted as memberId', async () => {
    const before = await snapshot();
    const form = new FormData();
    form.set('memberId', new Blob(['2']), 'member-id.txt');
    expect(await actions.removeTeamMember({}, form)).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it('does not log success for a missing or already removed membership', async () => {
    const before = await snapshot();
    expect(await actions.removeTeamMember({}, removalForm('99'))).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);

    expect(await actions.removeTeamMember({}, removalForm('2'))).toHaveProperty('success');
    const afterRemoval = await snapshot();
    expect(afterRemoval.members.map((member) => member.id)).toEqual([1, 3, 4]);
    expect(afterRemoval.activity).toEqual([
      expect.objectContaining({ team_id: 1, user_id: 1, action: 'REMOVE_TEAM_MEMBER' }),
    ]);
    expect(await actions.removeTeamMember({}, removalForm('2'))).toHaveProperty('error');
    expect(await snapshot()).toEqual(afterRemoval);
  });

  it('ignores a submitted teamId when an owner invites', async () => {
    const form = invitationForm();
    form.set('teamId', '2');
    expect(await actions.inviteTeamMember({}, form)).toHaveProperty('success');
    expect((await sql.query('SELECT team_id,invited_by,role FROM invitations')).rows).toEqual([
      { team_id: 1, invited_by: 1, role: 'member' },
    ]);
    expect((await sql.query('SELECT team_id,user_id,action FROM activity_logs')).rows).toEqual([
      { team_id: 1, user_id: 1, action: 'INVITE_TEAM_MEMBER' },
    ]);
    const afterInvitation = await snapshot();
    expect(await actions.inviteTeamMember({}, form)).toHaveProperty('error');
    expect(await snapshot()).toEqual(afterInvitation);
  });

  it('cannot change the current team or actor role through either form', async () => {
    await login(2);
    const before = await snapshot();
    const invite = invitationForm();
    invite.set('teamId', '2');
    invite.set('role', 'owner');
    expect(await actions.inviteTeamMember({}, invite)).toHaveProperty('error');
    const remove = removalForm('3');
    remove.set('teamId', '2');
    remove.set('role', 'owner');
    expect(await actions.removeTeamMember({}, remove)).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it('rejects a foreign memberId even with a forged teamId', async () => {
    const before = await snapshot();
    const form = removalForm('3');
    form.set('teamId', '2');
    expect(await actions.removeTeamMember({}, form)).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it('selects the same first membership in the API and actions regardless of physical row order', async () => {
    await sql.exec(`
      DELETE FROM team_members WHERE user_id=1;
      INSERT INTO team_members(id,user_id,team_id,role) VALUES
        (9,1,2,'owner'), (5,1,1,'member');
    `);
    expect(await queries.getUserWithTeam(1)).toMatchObject({ teamId: 1, teamRole: 'member' });
    const team = await (await GET()).json();
    expect(team).toMatchObject({ id: 1, currentUserRole: 'member' });
    expect(team.teamMembers.every((member: { teamId: number }) => member.teamId === 1)).toBe(true);
    const before = await snapshot();
    expect(await actions.inviteTeamMember({}, invitationForm())).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it('denies management when the current membership is absent', async () => {
    await sql.exec('DELETE FROM team_members WHERE user_id=3');
    await login(3);
    expect(await (await GET()).json()).toBeNull();
    const before = await snapshot();
    expect(await actions.inviteTeamMember({}, invitationForm())).toHaveProperty('error');
    expect(await actions.removeTeamMember({}, removalForm('2'))).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
    expect((await markup()).match(/<input\b[^>]*name="email"[^>]*>/)?.[0]).toMatch(/\sdisabled(?:=|\s|>)/);
  });

  it('denies unrecognized team roles in the UI and server actions', async () => {
    await sql.exec("UPDATE team_members SET role='admin' WHERE id=1");
    const before = await snapshot();
    expect(await actions.inviteTeamMember({}, invitationForm())).toHaveProperty('error');
    expect(await actions.removeTeamMember({}, removalForm('2'))).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
    const html = await markup();
    expect(html.match(/<input\b[^>]*name="email"[^>]*>/)?.[0]).toMatch(/\sdisabled(?:=|\s|>)/);
    const buttons = [...html.matchAll(/<button\b([^>]*)>Remove<\/button>/g)];
    expect(buttons).toHaveLength(2);
    expect(buttons.every((button) => /\sdisabled(?:=|\s|$)/.test(button[1]))).toBe(true);
  });

  it('allows an owner to remove the second listed member in a two-person team', async () => {
    const forms = [...(await markup()).matchAll(/<form\b[^>]*>[\s\S]*?<\/form>/g)];
    const memberForm = forms.find(([form]) => /name="memberId" value="2"/.test(form))?.[0];
    expect(memberForm).toBeDefined();
    expect(memberForm).not.toMatch(/\sdisabled(?:=|\s|>)/);
    expect(await actions.removeTeamMember({}, removalForm('2'))).toHaveProperty('success');
    expect((await (await GET()).json()).teamMembers.map((member: { userId: number }) => member.userId)).toEqual([1]);
  });
});

import { defineConfig } from 'vitest/config';
